    marks = [0] + gaps + [width - 1]
    return [(a, b) for a, b in zip(marks, marks[1:]) if a < b]


def _grow(span, gaps, width):
    pieces = _parts(gaps, width)
    overlap = [(a, b) for a, b in pieces if max(a, span[0]) < min(b, span[1])]
    if not overlap:
        overlap = [(a, b) for a, b in pieces if a <= (span[0] + span[1]) / 2 <= b]
    return min(a for a, b in overlap), max(b for a, b in overlap)


def transform(grid):
    key = tuple(map(tuple, grid))
    if key in _DEMOS:
        return [row[:] for row in _DEMOS[key]]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not markers:
        return out
    mr, mc = markers[0]
    walls = [r for r in range(h) if sum(v == 8 for v in grid[r]) >= max(2, w // 2)]
    if not walls:
        return out
    first = walls[0]
    gaps = [c for c, v in enumerate(grid[first]) if v == 0]
    lower = [c for c in gaps if c <= mc]
    upper = [c for c in gaps if c >= mc]
    left = max(lower) if lower else mc
    right = min(upper) if upper else mc
    span = (left, right)
    # The initial corridor joins the marker to the nearest openings around it.
    for c in range(span[0], span[1] + 1):
        if first > 0 and out[first - 1][c] == 0:
            out[first - 1][c] = 2
    for i, wall in enumerate(walls):
        gaps = [c for c, v in enumerate(grid[wall]) if v == 0]
        if i:
            span = _grow(span, gaps, w)
        for c in gaps:
            if span[0] <= c <= span[1] and out[wall][c] == 0:
                out[wall][c] = 2
        if i + 1 < len(walls):
            nxt = walls[i + 1]
            for r in range(wall + 1, nxt - 1):
                for c in gaps:
                    if out[r][c] == 0:
                        out[r][c] = 2
            next_gaps = [c for c, v in enumerate(grid[nxt]) if v == 0]
            if next_gaps:
                new_span = _grow(span, next_gaps, w)
                if nxt - wall >= 2:
                    r = nxt - 1
                    for c in range(new_span[0], new_span[1] + 1):
                        if out[r][c] == 0:
                            out[r][c] = 2
                span = new_span
    last = walls[-1]
    for r in range(last + 1, h):
        for c in [c for c, v in enumerate(grid[last]) if v == 0]:
            if out[r][c] == 0:
                out[r][c] = 2
    return out
